on conflict (player_id) do update set
  gk_reflexes = excluded.gk_reflexes, gk_handling = excluded.gk_handling, gk_positioning = excluded.gk_positioning, marking = excluded.marking, tackling = excluded.tackling, positioning = excluded.positioning, heading = excluded.heading, passing = excluded.passing, vision = excluded.vision, technique = excluded.technique, stamina = excluded.stamina, finishing = excluded.finishing, off_ball = excluded.off_ball, pace = excluded.pace, dribbling = excluded.dribbling, strength = excluded.strength, method = excluded.method, updated_at = now()
  where public.sim_player_attrs.estimated;   -- atributos curados à mão (estimated = false) são preservados

select public.sim_refresh_ratings();
commit;

-- conferência
select c.id, count(p.*) as jogadores from public.sim_clubs c left join public.sim_players p on p.club_id = c.id and p.active group by c.id order by 1;
